<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($pageTitle) ?> | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/orders.css">
<link rel="stylesheet" href="/assets/css/payouts.css"></head><body class="dashboard-page"><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/account">Dashboard</a><a href="/logout">Sign out</a></nav></header><main class="orders-shell"><p class="eyebrow"><?= htmlspecialchars($eyebrow) ?></p><h1><?= htmlspecialchars($heading) ?></h1><?php if ($vendor): ?><div class="earnings-grid"><article><small>Vendor earnings</small><strong>₹<?= number_format((float) $earnings['gross_earnings'], 0) ?></strong></article><article><small>Platform commission</small><strong>₹<?= number_format((float) $earnings['platform_commission'], 0) ?></strong></article><article><small>Eligible payout</small><strong>₹<?= number_format(array_sum(array_column($eligibleItems, 'amount')), 0) ?></strong></article></div><div class="payout-actions"><a class="button" href="/vendor/bank">Bank details</a><form method="post" action="/vendor/payouts/request"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><button class="button" type="submit">Request eligible payout</button></form></div><?php endif; ?><div class="orders-table"><div class="order-row order-header"><span>ID</span><span>Vendor</span><span>Amount</span><span>Status</span><span>Date</span></div><?php foreach ($payouts as $payout): ?><div class="order-row"><strong>#<?= htmlspecialchars($payout['id']) ?></strong><span><?= htmlspecialchars($payout['vendor']) ?></span><strong>₹<?= number_format((float) $payout['amount'], 0) ?></strong><i class="status-<?= htmlspecialchars($payout['status']) ?>"><?= htmlspecialchars(ucfirst($payout['status'])) ?></i><span><?= htmlspecialchars(date('d M Y', strtotime($payout['requested_at']))) ?></span><?php if ($adminView && in_array($payout['status'], ['pending', 'approved'], true)): ?><form method="post" action="/admin/payouts/review"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="payout_id" value="<?= htmlspecialchars($payout['id']) ?>"><select name="status"><option value="approved">Approve</option><option value="paid">Mark paid</option><option value="rejected">Reject</option></select><button class="button" type="submit">Save</button></form><?php endif; ?></div><?php endforeach; ?></div><?php if (!$payouts): ?><p class="empty-state">No payout records yet.</p><?php endif; ?></main></body></html>